<?php require 'config/database.php';$pageTitle='Resumes';$rows=$conn->query('SELECT r.*,u.name FROM resumes r JOIN users u ON u.user_id=r.seeker_id ORDER BY r.resume_id DESC');include 'includes/header.php';?><section class="card"><h1>RESUME</h1><div class="table-wrap"><table><tr><th>ID</th><th>Applicant</th><th>Preview</th><th>File</th><th>Type</th><th>Date</th></tr><?php while($r=$rows->fetch_assoc()):$ext=strtolower(pathinfo($r['file_name'],PATHINFO_EXTENSION));$isImage=in_array($ext,['jpg','jpeg','png'],true);?><tr><td><?=$r['resume_id']?></td><td><?=htmlspecialchars($r['name'])?></td><td><?php if($isImage):?><a href="<?=htmlspecialchars($r['file_path'])?>" target="_blank"><img class="resume-thumb" src="<?=htmlspecialchars($r['file_path'])?>" alt="Résumé preview"></a><?php else:?><span class="file-badge">DOC</span><?php endif;?></td><td><a href="<?=htmlspecialchars($r['file_path'])?>" target="_blank"><?=htmlspecialchars($r['file_name'])?></a></td><td><?=htmlspecialchars($r['file_type'])?></td><td><?=$r['upload_date']?></td></tr><?php endwhile;?></table></div></section><?php include 'includes/footer.php';?>
